// Chat with agent Sample agent
// Node 18+ (global fetch). Run with: npx tsx swfte-call.ts  (export SWFTE_API_KEY first)
const BASE_URL = "https://api.example.test/agents";
const headers: Record<string, string> = {
  Authorization: `Bearer ${process.env.SWFTE_API_KEY}`,
  "Content-Type": "application/json",
};

async function main() {
  const userId = "demo-user"; // any stable id for your end user; conversations are kept per userId
  const res = await fetch(`${BASE_URL}/v1/agents/agent_1/chat/${encodeURIComponent(userId)}`, {
    method: "POST",
    headers,
    body: JSON.stringify({
      "message": "Hello"
    }),
  });
  if (!res.ok) throw new Error(`HTTP ${res.status}: ${await res.text()}`);
  const data = await res.json();
  console.log(data["content"] ?? data["response"]);
}

main().catch((err) => {
  console.error(err);
  process.exit(1);
});
